 void validateCard(JSONObject input)throws Exception{String source=input.optString("sourceUrl");if(!source.isEmpty()&&!source.matches("(?i)^https?://.*"))throw new ApiError(400,"invalid_source","来源链接需要 HTTP(S) 地址");if(!Arrays.asList("draft","preset","snippet","style","starter","character","negative","parameters","favorite").contains(input.optString("kind"))||input.optString("title").trim().isEmpty()||input.optString("title").trim().length()>120)throw new ApiError(400,"invalid_card","预设类型或名称无效");String cover=input.optString("cover");if(!cover.isEmpty()&&(!cover.matches("(?s)^data:image/(png|jpeg|webp);base64,.*")||cover.length()>3*1024*1024))throw new ApiError(400,"invalid_cover","封面格式或大小无效");}
