 JSONArray cards(Map<String,String> q,boolean full)throws Exception{List<JSONObject> rows=new ArrayList<>();JSONArray list=store.list("library");String search=query(q,"q","").toLowerCase(Locale.ROOT),kind=query(q,"kind","");for(int i=0;i<list.length();i++){JSONObject e=list.getJSONObject(i);if(!e.isNull("deletedAt")||(!kind.isEmpty()&&!kind.equals(e.optString("kind"))))continue;if("1".equals(q.get("today"))&&!Instant.parse(e.getString("createdAt")).atZone(ZoneId.systemDefault()).toLocalDate().equals(LocalDate.now()))continue;if(!search.isEmpty()&&!(e.optString("title")+e.optString("category")+e.optString("notes")+e.optString("text")).toLowerCase(Locale.ROOT).contains(search))continue;JSONObject row=FxStorage.cloneJson(e);if(!full)row.remove("payload");rows.add(row);}rows.sort((a,b)->b.optString("updatedAt").compareTo(a.optString("updatedAt")));return new JSONArray(rows);}
