 JSONArray history()throws Exception{JSONArray a=store.list("history");List<JSONObject> list=new ArrayList<>();for(int i=0;i<a.length();i++)list.add(a.getJSONObject(i));list.sort((x,y)->y.optString("createdAt").compareTo(x.optString("createdAt")));return new JSONArray(list);}
