 static String mime(String filename){String f=filename.toLowerCase(Locale.ROOT);if(f.endsWith(".png"))return "image/png";if(f.endsWith(".webp"))return "image/webp";if(f.endsWith(".gif"))return "image/gif";if(f.endsWith(".avif"))return "image/avif";if(f.endsWith(".jpg")||f.endsWith(".jpeg"))return "image/jpeg";if(f.endsWith(".js")||f.endsWith(".mjs"))return "text/javascript; charset=utf-8";if(f.endsWith(".css"))return "text/css; charset=utf-8";if(f.endsWith(".html"))return "text/html; charset=utf-8";if(f.endsWith(".json"))return "application/json; charset=utf-8";if(f.endsWith(".woff2"))return "font/woff2";if(f.endsWith(".ttf"))return "font/ttf";if(f.endsWith(".svg"))return "image/svg+xml";return "application/octet-stream";}
